  BIND(?d1 AS ?earlierDate)
  OPTIONAL { ?later rdfs:label ?laterLabel . FILTER(lang(?laterLabel) = "en") }
  OPTIONAL { ?earlier rdfs:label ?earlierLabel . FILTER(lang(?earlierLabel) = "en") }
}
